rd<-function(n){d<-read.csv(file.path(DATA,paste0(n,'.csv')),check.names=FALSE,stringsAsFactors=FALSE);for(k in names(d))if(is.character(d[[k]])&&length(na.omit(d[[k]]))>0&&all(na.omit(d[[k]])%in%c('True','False')))d[[k]]<-ifelse(is.na(d[[k]]),NA,d[[k]]=='True');d}
short<-function(x){for(k in c('nonclassical_mono','classical_mono','microglia_homeostatic','microglia_mhc2','astro_fibrous','astro_protoplasmic','astro'))x<-gsub(k,c(nonclassical_mono='nMono',classical_mono='cMono',microglia_homeostatic='MG-H',microglia_mhc2='MG-AP',astro_fibrous='Fibrous astro',astro_protoplasmic='Protoplasmic astro',astro='Astro')[[k]],x,fixed=TRUE);x<-gsub('raw::','',x,fixed=TRUE);x<-gsub('relative::','Rel. ',x,fixed=TRUE);x<-gsub('__up',' +',x,fixed=TRUE);x<-gsub('__down',' -',x,fixed=TRUE);x<-gsub('__x__','>',x,fixed=TRUE);gsub('__',' ',x,fixed=TRUE)}
wrap<-function(x,n=25)vapply(x,function(y)paste(strwrap(y,n),collapse='\n'),'')
common<-theme(text=element_text(family='Helvetica',size=12),axis.text=element_text(size=12,color='#222222'),axis.text.x=element_text(size=12,color='#222222'),axis.text.y=element_text(size=12,color='#222222'),axis.title=element_text(size=13,face='bold'),axis.title.x=element_text(size=13,face='bold'),axis.title.y=element_text(size=13,face='bold'),strip.text=element_text(size=13,face='bold'),legend.title=element_text(size=12,face='bold'),legend.text=element_text(size=12),legend.key.size=unit(3,'mm'),plot.title=element_blank(),plot.subtitle=element_blank(),plot.caption=element_blank(),plot.tag=element_blank(),plot.margin=margin(31,8,7,8),panel.spacing=unit(4,'mm'))
box<-theme(panel.border=element_rect(color='#252525',fill=NA,linewidth=.45),axis.line=element_blank())
