DRAW_ONLY<-strsplit(Sys.getenv('PD_DRAW_ONLY',unset=''),',',fixed=TRUE)[[1]];DRAW_ONLY<-DRAW_ONLY[nzchar(DRAW_ONLY)]
wanted<-function(id)!length(DRAW_ONLY)||id%in%DRAW_ONLY
used<-if(length(DRAW_ONLY))fromJSON(file.path(W,'template_usage.json'),simplifyVector=FALSE)else list();manifest<-if(length(DRAW_ONLY))fromJSON(file.path(W,'panel_manifest.json'),simplifyVector=FALSE)else list()
P<-function(id,template,d,...){used[[id]]<<-list(template=template,n=nrow(d),source='R copied ordinary factory');p<-do.call(FACTORIES[[template]],c(list(d=d),list(...)));th<-p$theme;p<-p+common;for(k in names(th))if(inherits(th[[k]],'element_blank')&&grepl('axis',k))p$theme[[k]]<-th[[k]];if(template%in%c('6_I','5_C','7_J','2_E'))p<-p+theme(axis.text=element_blank(),axis.text.x=element_blank(),axis.text.y=element_blank(),axis.title=element_blank(),axis.title.x=element_blank(),axis.title.y=element_blank(),axis.ticks=element_blank(),axis.line=element_blank());p}
letter<-function(id)grid.text(toupper(sub('^[0-9]+','',id)),unit(4,'pt'),unit(1,'npc')-unit(5,'pt'),just=c('left','top'),gp=gpar(fontfamily='Helvetica',fontsize=16,fontface='bold'))
export<-function(p,id,nx=2,ny=2,outer_margin=margin(31,14,11,14)){
 if(!wanted(id))return(invisible(p))
 pdf(file.path(BUILD,paste0(id,'.pdf')),width=U*nx,height=U*ny,family='Helvetica',useDingbats=FALSE);print(p+labs(tag=NULL)+theme(plot.margin=outer_margin));letter(id);dev.off()
 saveRDS(p,file.path(BUILD,paste0(id,'.rds')));manifest[[id]]<<-list(id=id,units_x=nx,units_y=ny,width_in=U*nx,height_in=U*ny,width_px=1500*nx,height_px=1500*ny,base_unit_px=1500);cat('DRAW',id,'\n')
}
# Stable cohort-description panels retain their original actual-data plot objects.
fixg<-function(g,context=''){
 context<-paste(context,g$name)
 if(inherits(g,'text')){g$gp$fontsize<-if(grepl('axis.title',context))13 else 12;g$gp$fontfamily<-'Helvetica'}
 if(!is.null(g$grobs))g$grobs<-lapply(g$grobs,function(a)fixg(a,context))
 if(!is.null(g$children))g$children<-do.call(gList,lapply(g$children,function(a)fixg(a,context)));g
}
spatial_reflow<-function(p,ncol=5,fraction=FALSE){
 z<-p$data;lev<-unique(as.character(z$region));ps<-lapply(lev,function(v){q<-p;q$data<-z[as.character(z$region)==v,];q<-q+facet_null()+coord_equal()+theme_void();if(fraction)q<-q+scale_color_gradientn(colors=c('#F5F1DF','#E8B080','#CA6B6E','#8D234C'),trans='sqrt',limits=c(0,1),na.value='#D4D7D8');q<-q+theme_void()+theme(legend.position='none',plot.margin=margin(12,2,1,2));ggdraw()+draw_plot(q,0,0,1,.92)+draw_label(v,.5,.965,size=12)})
 leg<-get_legend(p+theme(legend.position='bottom')+guides(color=guide_colorbar(title.position='top',barwidth=unit(36,'mm'),barheight=unit(2,'mm'),nbin=100))+scale_color_gradient(low='#F5F0D9',high='#A43753',limits=if('value'%in%names(z)&&max(z$value,na.rm=TRUE)<=1)c(0,1)else range(z$value,na.rm=TRUE),breaks=if('value'%in%names(z)&&max(z$value,na.rm=TRUE)<=1)c(0,.5,1)else waiver(),na.value='#D4D7D8'))
 if(fraction)leg<-get_legend(p+theme(legend.position='bottom')+scale_color_gradientn(colors=c('#F5F1DF','#E8B080','#CA6B6E','#8D234C'),trans='sqrt',limits=c(0,1),na.value='#D4D7D8',breaks=c(0,.25,.5,1))+guides(color=guide_colorbar(title.position='top',barwidth=unit(48,'mm'),barheight=unit(2,'mm'))));ggdraw()+draw_plot(plot_grid(plotlist=ps,ncol=ncol),0,.12,1,.86)+draw_plot(leg,0,0,1,.12)
}
