 p$data$target<-gsub('Monocyte_CD14','CD14 mono',p$data$target);p$data$target<-gsub('Monocyte_CD16','CD16 mono',p$data$target)
 strata<-ggplot_build(p)$data[[2]];p$layers<-p$layers[1:2]
 strata$label<-gsub('_',' ',as.character(strata$stratum));strata$lx<-ifelse(strata$x==1,.8,2.2);strata$ly<-strata$y
 for(xx in unique(strata$x)){ii<-which(strata$x==xx);ii<-ii[order(strata$y[ii])];strata$ly[ii]<-seq(2000,max(strata$ymax)-2000,length.out=length(ii))}
 p<-p+geom_segment(data=strata,aes(x=x+ifelse(x==1,-.13,.13),y=y,xend=lx,yend=ly),inherit.aes=FALSE,linewidth=.3,color='#888888')+geom_text(data=strata,aes(lx,ly,label=label,hjust=ifelse(x==1,1,0)),inherit.aes=FALSE,size=12/ggplot2::.pt)+coord_cartesian(xlim=c(.50,2.42),expand=FALSE,clip='off')
 }
 if(id=='1h'){p<-p+theme_void()+facet_wrap(~region,ncol=5)+theme(strip.text=element_text(size=12),legend.position='bottom',legend.title=element_text(size=12),legend.text=element_text(size=12))+labs(x=NULL,y=NULL);p$layers[[1]]$aes_params$size<-.5;p<-spatial_reflow(p,5)}
 if(id%in%c('1b','1c')){
  source(file.path(W,'source',paste0(if(id=='1b')'rings_grid'else'umap_grid','.R')));p<-if(id=='1b')rings_grid()else umap_grid();nx<-as.numeric(entry[3]);ny<-as.numeric(entry[4]);pdf(file.path(BUILD,paste0(id,'.pdf')),width=U*nx,height=U*ny,family='Helvetica',useDingbats=FALSE);grid.newpage();grid.draw(fixg(ggplotGrob(p)));letter(id);dev.off();manifest[[id]]<-list(id=id,units_x=nx,units_y=ny,width_in=U*nx,height_in=U*ny,width_px=1500*nx,height_px=1500*ny,base_unit_px=1500)
 }else export(p,id,as.numeric(entry[3]),as.numeric(entry[4]))
 used[[id]]<-list(template=c('1b'='1_A','1c'='3_B','1d'='7_G','1e'='5_E','1f'='2_E','1h'='5_C')[[id]],source=paste0('panel_grid/objects/',entry[2],'.rds'),question='unchanged source-cohort description; layout and physical typography redrawn')
}
